def path(d,fill,stroke=None,sw=None,extra=''):
    return '<path d="'+d+'" fill="'+fill+'"'+(f' stroke="{stroke}" stroke-width="{sw}" stroke-linejoin="round"' if stroke else '')+' '+extra+'/>'

def lettering(names,transforms=None):
    result=[]
    for i,name in enumerate(names):
        d=glyphs[name]
        t=transforms[i] if transforms else ''
        result.append('<g'+(f' transform="{t}"' if t else '')+'>')
        result.append(path(d,DEEP,RED,27,'transform="translate(0 4)" fill-rule="evenodd"'))
        result.append(path(d,INK,INK,13,'transform="translate(0 7)" fill-rule="evenodd"'))
        result.append(path(d,WHITE,INK,8,'fill-rule="evenodd"'))
        result.append('</g>')
    return ''.join(result)

def svg(body,view,w,h):
    return f'<svg xmlns="http://www.w3.org/2000/svg" width="{w}" height="{h}" viewBox="{view}">{body}</svg>'

